SELECT COUNT(*) AS delivered_orders
FROM orders
WHERE order_status = 'delivered';

SELECT COUNT(DISTINCT customer_unique_id) AS customers
FROM customers
WHERE customer_state = 'MG';

SELECT ROUND(AVG(payment_installments), 2) AS avg_installments
FROM payments
WHERE payment_type = 'credit_card';

SELECT ROUND(AVG(date_diff('minute', order_purchase_timestamp, order_approved_at)) / 60.0, 2) AS avg_hours_to_approval
FROM orders
WHERE order_approved_at IS NOT NULL;
